{
  "category_edits": [
    {
      "category": "interaction_mechanism",
      "rationale": "Add jointly trained rank-8 bilinear compatibility: s(h,e)=h·e+0.1(Uh)·(Ve). Xavier initialization for U and zero initialization for V preserve initial dot-product scores. The Transformer, features, readout, loss, optimizer and category routing remain unchanged.",
      "edits": [
        {
          "find": "        self.last_layernorm = nn.LayerNorm(hidden_units, eps=1e-8)\n\n    def log2feats",
          "replace": "        self.last_layernorm = nn.LayerNorm(hidden_units, eps=1e-8)\n        self.compat_user = nn.Linear(hidden_units, 8, bias=False)\n        self.compat_item = nn.Linear(hidden_units, 8, bias=False)\n        nn.init.xavier_uniform_(self.compat_user.weight)\n        nn.init.zeros_(self.compat_item.weight)\n\n    def compatibility(self, user_feats: torch.Tensor,\n                      item_feats: torch.Tensor) -> torch.Tensor:\n        base = (user_feats * item_feats).sum(dim=-1)\n        interaction = (\n            self.compat_user(user_feats) * self.compat_item(item_feats)\n        ).sum(dim=-1)\n        return base + 0.1 * interaction\n\n    def log2feats"
        },
        {
          "find": "        pos_logits = (log_feats * pos_embs).sum(dim=-1)\n        neg_logits = (log_feats * neg_embs).sum(dim=-1)",
          "replace": "        pos_logits = self.compatibility(log_feats, pos_embs)\n        neg_logits = self.compatibility(log_feats, neg_embs)"
        },
        {
          "find": "        return item_embs.matmul(final_feat.unsqueeze(-1)).squeeze(-1)",
          "replace": "        return self.compatibility(final_feat.unsqueeze(1), item_embs)"
        },
        {
          "find": "            \"interest_aggregation\": \"causal_recency_half_life_5_blend_0.2_v1\",\n            \"hidden_units\": HIDDEN_UNITS,",
          "replace": "            \"interest_aggregation\": \"causal_recency_half_life_5_blend_0.2_v1\",\n            \"interaction_mechanism\": \"dot_plus_bilinear_rank8_scale0.1_v1\",\n            \"hidden_units\": HIDDEN_UNITS,"
        },
        {
          "find": "        # The imported SASRec applies the same causal recency readout as training.\n        _metas[ds] = meta",
          "replace": "        if meta.get(\"interaction_mechanism\") != \"dot_plus_bilinear_rank8_scale0.1_v1\":\n            raise ValueError(f\"Unexpected interaction mechanism configuration for {ds}\")\n        # The imported SASRec includes both jointly trained compatibility projections;\n        # strict checkpoint loading restores them alongside the Transformer weights.\n        _metas[ds] = meta"
        }
      ]
    }
  ],
  "change_summary": "Introduce zero-initialized residual bilinear scoring in each category's single SASRec model, consistently used for training and prediction, with predictor metadata validation."
}
